  "bud.feesEach": { en: "Fees each", ms: "Yuran seorang", zh: "每人费用" },
  "bud.unpriced": { en: "Paid courses with no price in our catalogue yet (not counted above; ask the provider): {list}.", ms: "Kursus berbayar yang belum ada harga dalam katalog kami (tidak dikira di atas; tanya penyedia): {list}.", zh: "目录中尚无价格的付费课程（未计入上方金额，请向课程方询问）：{list}。" },
  "bud.source": { en: "Estimates for planning, not quotes. Fees: the Laluan course catalogue, with each provider's price and HRD Corp status as of the date we checked; an employer claims HRD Corp only for approved training, applied for before it starts. Staff time: learning hours × the DOSM {year} median monthly pay of each person's current occupation group ÷ 173 working hours; a group figure, not anyone's salary.", ms: "Anggaran untuk perancangan, bukan sebut harga. Yuran: katalog kursus Laluan, dengan harga dan status HRD Corp setiap penyedia pada tarikh kami menyemaknya; majikan hanya boleh menuntut HRD Corp untuk latihan yang diluluskan dan dipohon sebelum ia bermula. Masa kakitangan: jam pembelajaran × gaji bulanan penengah DOSM {year} bagi kumpulan pekerjaan semasa setiap orang ÷ 173 jam bekerja; angka kumpulan, bukan gaji sesiapa.", zh: "用于规划的估计，不是报价。费用：Laluan 课程目录，按我们核对当日各课程方的价格和 HRD Corp 状态；雇主只能为已获批、且在开课前申请的培训申领 HRD Corp。员工时间：学习时数 × 每人目前职业类别的 DOSM {year} 月薪中位数 ÷ 173 个工作小时；这是职业类别数字，不是任何人的薪水。" },
  "hist.title": { en: "How this forecast has changed ({n} forecasts)", ms: "Bagaimana unjuran ini berubah ({n} unjuran)", zh: "此预测的变化（共 {n} 次预测）" },
  "hist.sub": { en: "This role's outlook to the horizon year in every forecast Laluan has used, oldest first ({s} scenario).", ms: "Prospek peranan ini hingga tahun sasaran dalam setiap unjuran yang pernah digunakan Laluan, yang terawal dahulu (senario {s}).", zh: "Laluan 使用过的每次预测中，此职位到目标年份的前景，按时间先后排列（{s}情景）。" },
  "hist.same": { en: "no change", ms: "tiada perubahan", zh: "没有变化" },
  "hist.note": { en: "A new row appears each time an admin approves a trend refresh. Older forecasts are kept, never edited.", ms: "Baris baharu muncul setiap kali pentadbir meluluskan kemas kini trend. Unjuran lama disimpan dan tidak diubah.", zh: "每当管理员批准一次趋势刷新，就会新增一行。旧预测会保留，绝不修改。" },
  "aa.option": { en: "Option A · Level up where you are", ms: "Pilihan A · Tingkatkan diri di tempat anda sekarang", zh: "选项 A · 在现有岗位上提升" },
