  "aa.source": { en: "AI skills drafted from Laluan's AI-capability and O*NET task data, checked by our team; courses from the Laluan catalogue.", ms: "Kemahiran AI dirangka daripada data keupayaan AI dan tugasan O*NET Laluan, disemak oleh pasukan kami; kursus daripada katalog Laluan.", zh: "AI 技能根据 Laluan 的 AI 能力和 O*NET 任务数据起草，经团队审核；课程来自 Laluan 课程目录。" },
  "card.longShot": { en: "Long-term goal", ms: "Matlamat jangka panjang", zh: "长期目标" },
  "card.longShotHelp": { en: "You have less than a fifth of this role's skills, so it is a long route rather than a next move.", ms: "Anda mempunyai kurang daripada satu perlima kemahiran peranan ini, jadi ia laluan panjang dan bukan langkah seterusnya.", zh: "您具备的技能不到该职位所需的五分之一，所以它是一条长路线，而不是下一步。" },
  "card.newRole": { en: "New role, data being checked", ms: "Peranan baharu, data sedang disemak", zh: "新职位，数据核查中" },
  "card.newRoleHelp": { en: "Added to Laluan recently. Its skills, task labels and estimates were drafted with AI from O*NET, WEF and MASCO data and are still being checked by the team. Its growth figure is from WEF.", ms: "Baru ditambah ke Laluan. Kemahiran, label tugas dan anggarannya dirangka dengan AI daripada data O*NET, WEF dan MASCO dan masih disemak oleh pasukan. Angka pertumbuhannya daripada WEF.", zh: "最近加入 Laluan。其技能、任务标签和估算由 AI 根据 O*NET、WEF 和 MASCO 数据起草，团队仍在核查。增长数据来自 WEF。" },
