  "deg.note": { en: "Suggested from typical Malaysian programmes and checked by our team. Untick anything you didn't really learn.", ms: "Dicadangkan daripada program biasa di Malaysia dan disemak oleh pasukan kami. Nyahtanda apa-apa yang tidak benar-benar anda pelajari.", zh: "根据马来西亚常见专业的课程建议，并经团队审核。没有真正学过的请取消勾选。" },
  "class.byProgramme": { en: "By programme", ms: "Mengikut program", zh: "按专业" },
  "class.byProgrammeSub": { en: "Where each programme's students fit best and the gaps an add-on course could close. Programmes with fewer than 3 students are left out.", ms: "Di mana pelajar setiap program paling sesuai dan jurang yang boleh ditutup dengan kursus tambahan. Program dengan kurang daripada 3 pelajar tidak dipaparkan.", zh: "各专业学生最适合的职位，以及一门附加课程可以弥补的差距。少于 3 名学生的专业不显示。" },
