  "op.none": { en: "No Malaysian job ads came back this time. Try the job sites above.", ms: "Tiada iklan jawatan Malaysia ditemui kali ini. Cuba laman kerja di atas.", zh: "这次没有找到马来西亚的招聘广告，请试试上方的求职网站。" },
  "op.otherPages": { en: "Also found {n} other pages that are not job ads.", ms: "Turut ditemui {n} halaman lain yang bukan iklan jawatan.", zh: "另外找到 {n} 个非招聘广告的页面。" },
  "op.note": { en: "Found by a live web search with Gemini and Google Search; not checked by our team and never used in your ranking. Ads close quickly: check the date on the employer's page before you apply.", ms: "Ditemui melalui carian web langsung dengan Gemini dan Google Search; tidak disemak oleh pasukan kami dan tidak digunakan dalam kedudukan anda. Iklan cepat ditutup: semak tarikh di halaman majikan sebelum memohon.", zh: "通过 Gemini 和 Google 搜索实时找到；未经团队审核，也不会用于您的排名。招聘广告很快会关闭：申请前请在雇主页面核对日期。" },
