  "iv.title": { en: "Practise an interview", ms: "Latihan temu duga", zh: "模拟面试" },
  "iv.intro": { en: "Five questions for this role, starting with the skills you don't have yet. You get short feedback after each answer. Nothing is saved.", ms: "Lima soalan untuk peranan ini, bermula dengan kemahiran yang belum anda miliki. Anda menerima maklum balas ringkas selepas setiap jawapan. Tiada apa yang disimpan.", zh: "针对该职位的五个问题，从您尚未掌握的技能开始。每次回答后都会得到简短反馈。不会保存任何内容。" },
  "iv.start": { en: "Start practice", ms: "Mula latihan", zh: "开始练习" },
  "iv.answer": { en: "Your answer", ms: "Jawapan anda", zh: "您的回答" },
  "iv.send": { en: "Answer", ms: "Jawab", zh: "回答" },
  "iv.feedback": { en: "Feedback", ms: "Maklum balas", zh: "反馈" },
  "iv.done": { en: "That's all five. Say your answers out loud once more before the real interview.", ms: "Itu sahaja lima soalan. Sebut jawapan anda sekali lagi dengan kuat sebelum temu duga sebenar.", zh: "五个问题已完成。正式面试前，请再大声说一遍您的回答。" },
  "iv.again": { en: "Practise again", ms: "Berlatih lagi", zh: "再练一次" },
  "iv.note": { en: "Practice only: the feedback is a suggestion, not a judgement of you. Personal details are removed before any AI reads your answers.", ms: "Latihan sahaja: maklum balas ialah cadangan, bukan penilaian terhadap anda. Butiran peribadi dibuang sebelum AI membaca jawapan anda.", zh: "仅供练习：反馈只是建议，不是对您的评判。AI 读取您的回答前会先删除个人信息。" },
  "iv.error": { en: "Couldn't reach the server. Try again.", ms: "Tidak dapat menghubungi pelayan. Cuba lagi.", zh: "无法连接服务器，请重试。" },
  "exp.title": { en: "Where experts disagree: AI exposure", ms: "Di mana pakar tidak sependapat: pendedahan kepada AI", zh: "专家分歧之处：AI 影响程度" },
  "exp.intro": { en: "Three published studies, each on its own scale. The figure is how many occupations in that study are less exposed than this one.", ms: "Tiga kajian yang diterbitkan, masing-masing dengan skala sendiri. Angka ini menunjukkan berapa banyak pekerjaan dalam kajian itu yang kurang terdedah berbanding pekerjaan ini.", zh: "三项已发表的研究，各有各的尺度。数字表示该研究中有多少比例的职业受影响程度低于此职业。" },
