  "exp.ofOccupations": { en: "of occupations in published studies", ms: "pekerjaan dalam kajian yang diterbitkan", zh: "已发表研究中的职业" },
  "exp.see": { en: "See the studies", ms: "Lihat kajian", zh: "查看研究" },
