  "exp.studies": { en: "the studies rank it", ms: "kajian meletakkannya di kedudukan", zh: "各研究将其排在" },
  "exp.flag": { en: "Laluan's estimate sits outside every published study for this role, so it is flagged for our team to review. Rankings still use our estimate until a person decides.", ms: "Anggaran Laluan berada di luar semua kajian yang diterbitkan untuk peranan ini, jadi ia ditanda untuk disemak oleh pasukan kami. Kedudukan masih menggunakan anggaran kami sehingga seseorang membuat keputusan.", zh: "Laluan 对该职位的估算超出了所有已发表研究的范围，因此已标记待团队复核。在有人作出决定之前，排名仍使用我们的估算。" },
  "exp.rankNote": { en: "#1 is the most exposed of the roles compared.", ms: "#1 ialah yang paling terdedah antara peranan yang dibandingkan.", zh: "#1 表示在比较的职位中受影响最大。" },
