  "exp.mysAuto": { en: "AI does the task / helps the person:", ms: "AI melakukan tugas / membantu orang:", zh: "AI 完成任务 / 协助人完成：" },
  "exp.foot": { en: "Display only: rankings use Laluan's estimate. Studies cover US or global occupations, matched to this role by its closest occupation code.", ms: "Paparan sahaja: kedudukan menggunakan anggaran Laluan. Kajian meliputi pekerjaan AS atau global, dipadankan kepada peranan ini melalui kod pekerjaan terdekat.", zh: "仅供展示：排名使用 Laluan 的估算。研究涵盖美国或全球职业，按最接近的职业代码与此职位匹配。" },
  "map.title": { en: "AI exposure and job outlook", ms: "Pendedahan AI dan prospek pekerjaan", zh: "AI 影响程度与就业前景" },
  "map.sub": { en: "Right means more exposed to AI in published studies; up means more jobs expected. Your top five are highlighted. Tap a role to open it.", ms: "Ke kanan bermaksud lebih terdedah kepada AI dalam kajian yang diterbitkan; ke atas bermaksud lebih banyak pekerjaan dijangka. Lima teratas anda diserlahkan. Ketik peranan untuk membukanya.", zh: "越往右表示在已发表研究中受 AI 影响越大；越往上表示预计就业越多。您的前五名已高亮。点击职位可打开。" },
  "map.desc": { en: "Scatter chart of roles by AI exposure and job outlook", ms: "Carta serakan peranan mengikut pendedahan AI dan prospek pekerjaan", zh: "按 AI 影响程度与就业前景排列的职位散点图" },
